/* ── Flow create surface: placeholder slots, ghost nodes, drawer ─────────
   The slots are the flow view's create affordance: one dashed card per block
   kind column, quiet until hovered. A created-but-undeclared block renders
   as a ghost until `sys create` + refresh declares it. */

.rf-slot {
  width: 300px;
  height: 84px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  color: var(--text-muted);
  background: transparent;
  border: 1.5px dashed var(--border);
  border-radius: var(--radius);
  opacity: 0.6;
  cursor: pointer;
  transition:
    opacity 0.12s ease,
    border-color 0.12s ease,
    background 0.12s ease;
}

.rf-slot:hover {
  opacity: 1;
  border-color: var(--text-muted);
  background: var(--surface);
}

/* Dashed hairlines at 0.6 opacity all but vanish on the dark ground. */
:root[data-theme='dark'] .rf-slot {
  opacity: 0.75;
}

:root[data-theme='dark'] .rf-slot:hover {
  opacity: 1;
}

.rf-slot-plus {
  font-size: 22px;
  line-height: 1;
  flex: 0 0 auto;
}

.rf-slot-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.rf-slot-name {
  font-weight: 600;
}

.rf-slot-hint {
  font-size: 11px;
}

/* Ghost node: scaffolded but not in the declared topology yet. */
.rf-int.ghost {
  border-style: dashed;
  opacity: 0.65;
}

.rf-int.ghost .rf-int-name {
  color: var(--text-muted);
}

.rf-int-tag.ghost-tag {
  color: var(--accent);
  background: var(--accent-soft);
}

.rf-int-tag + .ghost-tag {
  margin-left: 6px;
}

/* The extractor's seed action: an icon button at the end of the card head,
   quiet until hover like the slot placeholders. The trailing tags keep their
   margins; the button only needs its own gap when it directly follows the
   name (no tags). */
.rf-int-seed {
  margin-left: 6px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  opacity: 0.55;
}

.rf-int-name + .rf-int-seed {
  margin-left: auto;
}

.rf-int-seed svg {
  width: 16px;
  height: 16px;
  fill: currentColor;
}

.rf-int:hover .rf-int-seed {
  opacity: 1;
}

.rf-int-seed:hover:not(:disabled) {
  background: var(--surface-2);
  color: var(--accent);
}

.rf-int-seed:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

/* Neutral informational banner (the ghost re-sync prompt). */
.banner.hint {
  color: var(--text-muted);
  background: var(--surface-2);
  border: 1px solid var(--border);
}

.banner.hint .flow-refresh {
  margin-left: 10px;
}

.banner.hint code {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
}

/* Create drawer: same geometry as the flow inspector, floating over the
   canvas' right edge. */
.create-drawer {
  position: absolute;
  top: 12px;
  right: 12px;
  bottom: 12px;
  width: min(420px, calc(100% - 24px));
  overflow-y: auto;
  padding: 16px 18px 24px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.18);
  z-index: 10;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.create-drawer-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 2px;
}

.create-drawer-title {
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.create-drawer-sys {
  font-size: 12px;
  color: var(--text-muted);
}

.drawer-show-all {
  align-self: flex-start;
  font: inherit;
  font-size: 12px;
  color: var(--text-muted);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  text-decoration: underline;
}

.drawer-show-all:hover {
  color: var(--text);
}

/* Locked destination prefix joined onto the out-dir input. */
.drawer-dir {
  display: flex;
  align-items: stretch;
}

.drawer-dir-prefix {
  display: flex;
  align-items: center;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
  color: var(--text-muted);
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-right: none;
  border-radius: 8px 0 0 8px;
  padding: 0 8px;
  white-space: nowrap;
}

.drawer-dir-prefix + input[type='text'] {
  border-radius: 0 8px 8px 0;
}

.drawer-dir input[type='text'] {
  flex: 1;
  min-width: 0;
}

